
DECLARE income jsonb;refs jsonb;aliases jsonb;f jsonb=p->'fields';target uuid=(p->>'targetId')::uuid;BEGIN
 SELECT to_jsonb(x) INTO income FROM public.fin_ingresos x WHERE id=target;IF income IS NULL THEN RAISE EXCEPTION 'Original financial income missing';END IF;
 IF EXISTS(SELECT 1 FROM public.hato_produccion_quincenal WHERE fin_ingreso_id=target AND origen_dato IS DISTINCT FROM 'derivado_mensual') OR EXISTS(SELECT 1 FROM hato_quincena.audit WHERE receipt->'before'->'income'->>'id'=target::text OR receipt->'after'->'income'->>'id'=target::text) OR EXISTS(SELECT 1 FROM hato_quincena.requests WHERE intent->>'targetId' IN(SELECT id::text FROM public.hato_produccion_quincenal WHERE fin_ingreso_id=target) AND NOT acknowledged AND state IN('pending','committed')) THEN RAISE EXCEPTION 'Protected measured/unknown milk claim requires its dedicated route';END IF;
 IF EXISTS(SELECT 1 FROM hato_sale.requests WHERE plan->>'incomeId'=target::text OR receipt->'income'->>'id'=target::text) OR EXISTS(SELECT 1 FROM hato_sale.audit WHERE receipt->'income'->>'id'=target::text) OR EXISTS(SELECT 1 FROM public.hato_eventos WHERE fin_ingreso_id=target) OR EXISTS(SELECT 1 FROM financial_sale_correction.requests WHERE intent->>'targetId'=target::text) THEN RAISE EXCEPTION 'Retained sale/event claim requires its dedicated reviewed route';END IF;
 IF EXISTS(SELECT 1 FROM hato_income_metadata.invoice_origins WHERE income_id=target) OR EXISTS(SELECT 1 FROM hato_income_metadata.audit WHERE receipt->'before'->'income'->>'id'=target::text OR receipt->'after'->'income'->>'id'=target::text) THEN RAISE EXCEPTION 'Retained measured metadata/invoice origin requires its dedicated route';END IF;
 IF EXISTS(SELECT 1 FROM hato_income_metadata.requests WHERE intent->>'targetId'=target::text AND NOT acknowledged AND state IN('pending','committed')) THEN RAISE EXCEPTION 'Recover original metadata outcome before financial correction';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO aliases FROM public.hato_produccion_quincenal q WHERE fin_ingreso_id=target;
 SELECT jsonb_build_object('business',(SELECT to_jsonb(x) FROM public.fin_negocios x WHERE id=(f->>'businessId')::uuid AND activo IS TRUE),'category',(SELECT to_jsonb(x) FROM public.fin_categorias_ingresos x WHERE id=(f->>'categoryId')::uuid AND negocio_id=(f->>'businessId')::uuid AND activo IS TRUE),'region',(SELECT to_jsonb(x) FROM public.fin_regiones x WHERE id=(f->>'regionId')::uuid AND activo IS TRUE),'medium',(SELECT to_jsonb(x) FROM public.fin_medios_pago x WHERE id=(f->>'mediumId')::uuid AND activo IS TRUE),'buyer',(SELECT to_jsonb(x) FROM public.fin_compradores x WHERE id=(f->>'buyerId')::uuid AND activo IS TRUE)) INTO refs;
 IF EXISTS(SELECT 1 FROM jsonb_each(refs)e WHERE e.value='null'::jsonb AND(e.key<>'buyer' OR f->'buyerId'<>'null'::jsonb)) THEN RAISE EXCEPTION 'Current active matching financial references required';END IF;
 RETURN jsonb_build_object('production',NULL,'income',income,'aliases',aliases,'beforeRefs',jsonb_build_object('business',(SELECT to_jsonb(x) FROM public.fin_negocios x WHERE id=(income->>'negocio_id')::uuid),'category',(SELECT to_jsonb(x) FROM public.fin_categorias_ingresos x WHERE id=(income->>'categoria_id')::uuid),'region',(SELECT to_jsonb(x) FROM public.fin_regiones x WHERE id=(income->>'region_id')::uuid),'medium',(SELECT to_jsonb(x) FROM public.fin_medios_pago x WHERE id=(income->>'medio_pago_id')::uuid),'buyer',(SELECT to_jsonb(x) FROM public.fin_compradores x WHERE id=(income->>'comprador_id')::uuid)),'refs',refs);
END 
